Any $\mu \in {\rm ex}\mathcal{G}(\gamma)$ is characterized by the equivalent items:
	\begin{enumerate}

		\item Tail-triviality:
		$
		A \in \mathcal{F}_\infty \Longrightarrow \mu(A) \in \{0,1\}.
		$
		\item Short-range correlations
	  	\begin{equation}\label{short}
		\lim_{\Lambda \uparrow V} \sup_{B \in \mathcal{F}_{\Lambda^c}} \big| \mu(A \cap B) - \mu(A) \mu(B) \big| = 0.
	 	\end{equation}
	\end{enumerate}

\label{pipoint}
	Assume that  $\mathcal{G}(\gamma)\neq \emptyset$. Then
	$\mathcal{G}(\gamma)$ is a convex subset of
	$\mathcal{M}_1^+(\Omega)$
	whose extreme boundary is denoted ${\rm ex} \mathcal{G}(\gamma)$, and satisfies  the following properties:
		\begin{equation}\label{Choquet}
			\forall \mu  \in \mathcal{G}(\gamma),\; \mu = \int_{{\rm ex}\mathcal{G}(\gamma)} \; \nu \cdot \alpha_\mu(d
			\nu)
		\end{equation}
		where $\alpha_\mu \in \mathcal{M}_1^+\Big({\rm
			ex}\mathcal{G}(\gamma),e({\rm ex} \mathcal{G}(\gamma))\Big)$ is
		defined for all $M \in e({\rm ex} \mathcal{G}(\gamma))$ by

		\begin{equation} \label{weights}
			\alpha_\mu (M) = \mu \Big[ \big \{ \omega \in \Omega: \pi(\cdot | \omega) 
			\in M\big \} \Big]. 
		\end{equation}

\label{def-p1}
	Let $\mu$ be a homogeneous tree-indexed Markov chain.
	Denote by $P$ its transition matrix (which is then homogeneous, too) and define the corresponding {maximal jump probability} to be  
	\begin{align}
	p_1=p_1(\mu):=\max_{i\in\mathbb Z_q }\sum_{j\neq i}P(i,j).
	\end{align}
	Equivalently, for all $v\sim 0$ we have  
	\begin{align}\label{def-p1-ter}
	p_1=\max_{i\in\mathbb Z_q }\mu(\sigma_v\neq i|\sigma_0=i ).
	\end{align}

\label{thm-reconstruction} 
Consider any central state $\mu$ in the class of models {with Hamiltonian of the form} \eqref{potential-central}, fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}. Then,
 there exists $\beta_0>0$ large enough such that for any $\beta>\beta_0$, for any $a\in{\mathbb Z}_q$,
	\begin{align}\label{eq-reconstruction}
	\mu\Bigl( \lbrace \omega:  
	\pi(\sigma_0=a|\omega)\leq 1- \epsilon_1(\beta) \rbrace
		\Bigl| \sigma_0=a  \Bigr) 
		\leq \epsilon_2 (p_1)
	\end{align}
	where $\epsilon_1(\beta)=\epsilon_1(\beta,u,U,d)\downarrow0$ as $\beta\uparrow\infty$ and $\epsilon_2(p_1)=\epsilon_2 (p_1,u,U,d)\downarrow0$ as $p_1\downarrow0$.\\
	In particular, if $\mu$ is the free state of a clock model, the reconstruction bound
	\begin{align}\label{eq-reconstruction-small}
				\int d\mu(\omega|	\sigma_0=a)\pi(\sigma_0=a|\omega)>\frac1q=\mu(\sigma_0=a)
	\end{align}
	holds at large enough $\beta$.

\label{def-qEA}
	\begin{equation}
		\begin{split}
		q_{\rm EA}^\mu




	&:=\frac1q\sum_{a\in {\mathbb Z}_q}{\rm Var}_\mu\bigl({\pi( {\sigma_0=a} | \cdot})\bigr).\cr
	\end{split}
	\end{equation}

\label{thm-sing-ex} 
	Consider any central state $\mu$ in the class of models {with Hamiltonian of the form} \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}. Then,
	there exist $\beta_0>0$ large enough and $p_1^0=p_1^0(\beta,u,U,d)>0$ small enough such that for any $\beta>\beta_0$, $p_1(\mu)<p_1^0$ and for $\mu\otimes\mu$-a.e.\ pair $(\omega,\omega')$ the extremal Gibbs measures 
$\pi(\cdot|\omega)$ and $\pi(\cdot|\omega')$ are singular with respect to each other, i.e.
\begin{align}
	\mu \otimes \mu\big(\{(\omega,\omega')\in \Omega\times \Omega : \pi(\cdot |\omega) \perp \pi(\cdot | \omega')\}\big)=1.
\end{align}

\label{cor-uncountably} {The decomposition measure $\alpha_\mu$ 
has no atoms,  i.e. $\alpha_\mu(\{\nu\})=0$ for all $\nu\in{\rm ex}\mathcal G(\gamma)$. In particular there are 
uncountably many extremal states which enter in the extremal decomposition of $\mu$. }

\label{def-branch-overlap}
	Define the tail-measurable function, called
	{\it thinned branch-overlap}, measuring how much the configuration $\sigma$ matches with $\omega$ on the increasing sparse volumes $\Lambda_n$, as
	\begin{equation}\begin{split}

	&\underline\phi^\omega=\liminf_{n\uparrow\infty}\frac{1}{|\Lambda^{\rm r}_n|}\sum_{v\in \Lambda^{\rm r}_n}1_{\sigma_v=\omega_v}.\cr
	\end{split}
	\end{equation}
	For any fixed configuration $\omega$, this is a tail-measurable observable 
	w.r.t.\ the dependence on the spins $\sigma$, which takes 
	values on the interval $[0,1]$. Analogous  tail-measurability also holds w.r.t.\ to the parameter $\omega$.

\label{thm-branch-overlap} 
	Consider any central state $\mu$ in the class of models {with Hamiltonian of the form} \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}. Then
there are two functions $\epsilon_1(\beta)\downarrow 0$ as $\beta\uparrow \infty$ and $\epsilon_2(p_1)\downarrow0$ as $p_1\downarrow0$ such that for sparse enough sets $\Lambda_n=\Lambda_n^{\rm r}$ 
the following holds:\\
For $\mu$-a.e. $\omega$, 
the thinned branch-overlap $\underline\phi^\omega$
{is $\pi(\cdot |\omega)$-a.s.\  lower bounded by}
\begin{equation}\begin{split}
\label{concentration-bound}
\underline\phi^\omega=
&\liminf_{n\uparrow\infty}\frac{1}{|\Lambda_n|}\sum_{v\in \Lambda_n}1_{\sigma_v=\omega_v}
\geq 1-\epsilon_1(\beta)-\epsilon_2(p_1).
\end{split}
\end{equation}

\label{cor-glassy}
Let $\beta$ be large enough and $p_1$ be small enough such that

\begin{equation}
\label{epsilon-small}
\epsilon_1(\beta)+\epsilon_2(p_1)


<\frac{1}{2}(1-{\sum_{a\in {\mathbb Z}_q}\mu(\sigma_0=a)^2}).
\end{equation}
Then there is a sequence 
of integers ${\rm r}=(r_i)_{i\in {\mathbb N}}$ such that for the correspondingly 
defined tail-measurable observable $\underline\phi^\omega$ we have the strict 
inequality 
	\begin{equation}
\begin{split}
\label{eq-glassy}
&\pi(\underline\phi^\omega|\omega)>\pi(
\underline\phi^\omega|\omega')
\end{split}
\end{equation}
for $\mu\otimes\mu$-a.e. $(\omega,\omega')$.

A {boundary law} $\lambda$ for a transfer matrix $Q$ is a family of row vectors { $\lambda_{vw} \in \; ]0,\infty[^{\mathbb{Z}_q}$} which satisfy, {for all {oriented pairs 
of nearest neighbors }$v,w \in V$},  the following consistency equation: there exists some $c_{vw} >0$ such that for all $i \in \mathbb{Z}_q$,

	\begin{equation*} \label{eq: perGenBL}
		\lambda_{vw}(i)=c_{vw}
		\prod_{z \in \partial \{v\} \setminus \{w\}} \sum_{j\in{\mathbb Z}_q}
		Q(i,j)\lambda_{zv}(j).
	\end{equation*}

\label{thm-BL} There is a one-to-one relation between 
	Gibbs measures $\mu$ which are also tree-indexed Markov chains and {boundary laws} $\lambda$. \\  
	{A} Gibbs measure $\mu$ is then described via its finite-volume marginals in any $\Lambda\Subset V$	in the form 
	\begin{equation}\label{BoundMC}
		\mu(\omega_{\Lambda \cup \partial \Lambda}) = (Z^\omega_\Lambda)^{-1} \prod_{w \in \partial \Lambda} \lambda_{w w_\Lambda}(\omega_w) \prod_{b \cap \Lambda \neq \emptyset} Q_b(\omega),
	\end{equation}
	where $w_{{\Lambda}}$ is the unique neighbor of $w\in \partial \Lambda$ 
	which lies in $\Lambda$. 
	The Markov chain transition operator is given {for all $v,w \in V$ by the stochastic matrix}
	\begin{equation}\label{transition-matrix}
		P_{vw}(\omega_v,\omega_w)=\frac{Q(\omega_v,\omega_w)\lambda_{wv}(\omega_w)}
		{\sum_{j\in{\mathbb Z}_q}Q(\omega_v,j)\lambda_{wv}(j)}. 
	\end{equation}

\label{lemma-middle} 

		Suppose that all eigenvalues of  $Q_0$ are different from $1/d$. 
		Then there is a neighborhood of $Q_0$ such that for all $Q$ in this neighborhood 
		there exists a continuously differentiable solution $Q\mapsto\bar x(Q)$ of the boundary law equation \eqref{BL-middle-state}
		for $Q$, which has the property that $\bar x(Q_0)=1$.

\label{LemmaQuant} Consider a clock model {with Hamiltonian} in the class  \eqref{model-clock} fulfilling the bound \eqref{uU-condition}. We have the lower bounds on the eigenvalues $\lambda_j$ of 
		the transition operator $Q_0=\frac{e^{-\beta \Phi}}{\Vert e^{-\beta \Phi} \Vert_1}$ of 
		the form 
		\begin{equation*} 
			\lambda_j \geq \frac{1-(q-1)e^{-\beta u}}{1+(q-1)e^{-\beta u}}.\end{equation*}

Clearly $\Vert e^{-\beta \Phi}  \Vert_1\leq 1+(q-1)e^{-\beta u}$. 
	To estimate the spectral radius of the symmetric matrix 
	$e^{-\beta \Phi}-id_q$, observing that for $v$ with $\Vert v \Vert_2=1$ 
	we have 
	\begin{equation} 
		\begin{split}
			&|\langle v, (e^{-\beta \Phi}-id_q)v\rangle |\leq e^{-\beta u} \sum_{i\neq j}|v_i| |v_j|\cr
			&= e^{-\beta u}( (\sum_{i}|v_i|)^2 -1)\leq e^{-\beta u} (q-1).
		\end{split}
	\end{equation}
	This implies that the eigenvalues of $e^{-\beta \Phi} $ are bounded below 
	by $1-e^{-\beta u} (q-1)$, which  proves the lemma. 
	\endproof

\label{lem-Peierls} {Consider  $\omega^0 \in \Omega$ and a volume $\Lambda \Subset V$. Then}
	\begin{align}
		\mu^{\omega^0}_\Lambda(\sigma_v\neq\omega^0_v)
		&=\sum_{\bar\gamma:\gamma\ni v}^{\Lambda}
		\rho[\omega^0](\bar\gamma) \cdot
	\frac{{\sum_n}\sum^{\Lambda}_{\bar\gamma_1,\dots, \bar\gamma_n \sim \bar\gamma}\prod_{i=1}^n \rho[\omega^0](\bar\gamma_i)}{
	{\sum_n}\sum^{\Lambda}_{\bar\gamma_1,\dots, \bar\gamma_n}\prod_{i=1}^n 
	\rho[\omega^0](\bar\gamma_i)}\nonumber\\
	&\leq \sum_{\bar\gamma:\gamma\ni v}^{\Lambda}
		\rho[\omega^0](\bar\gamma).
	\end{align}
	where the sum is over contours $\bar\gamma$ in the finite volume $\Lambda$.

\emph{}\\
We define the set of broken bonds of the configuration $\omega\in\Omega$ by
$$D(\omega)=\{(v,w)\in E:\omega_v\neq\omega_w\}$$
and denote the set of edges attached to $\gamma\subset V$ by
\begin{equation}
\begin{split}
E(\gamma)&=\{\{x,y\}\in E,  \{x,y\} \cap \gamma \neq \emptyset  \}.
\end{split}
\end{equation}

\label{lem-entropy}
	We have the following upper bound on the number of connected subsets of vertices of $\mathcal T^d=(V,E)$:
	$$\#\{\gamma\subset V : \gamma \text{ connected ,} \gamma\ni 0,|\gamma|=\ell\}\leq(d+1)^{2(\ell-1)}.$$

\label{lem-EEL}\emph{}\\
	Let $\mu$ be a central state of any model {with Hamiltonian} in the class \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}.
	Let $\bar\gamma=(\omega'_{\gamma},\gamma)$ 
	be a contour relative to the fixed configuration 
	$\omega$. 
	Denote $\omega'=(\omega'_{\gamma}\omega_{\gamma^c})$ 
	the corresponding excited spin configuration. 
	Then the excess energy satisfies
	\begin{equation}
	\begin{split}	
	\label{XSfinite}
	H(\omega')&- H(\omega) 
	\geq \\
	&(d-1)u |\gamma|-(U+u) | D(\omega)\cap E(\gamma) | 
	+\sum_{v\in\gamma} (\Psi(\omega'_v)-\Psi(\omega_v)).


	\end{split}
	\end{equation}
	In particular, if there exist $\delta\geq0$ and $\epsilon>0$ such that $| D(\omega)\cap E(\gamma) | \leq\delta|\gamma|$ and $\Vert\Psi\Vert_\infty\leq\epsilon/2$ then
	\begin{equation}	\label{EEL-constant}
		H(\omega')- H(\omega) 
		\geq |\gamma|\Big((d-1)u-(U+u)\delta-\epsilon\Big).
	\end{equation}

\label{def-bad} 
	Consider any model in the class \eqref{potential-central}. Let 
\begin{equation}\label{def-delta0}
	\delta_0:=\frac12\cdot\frac{(d-1)u}{(u+U)}
\end{equation}
where $u,U\in{\mathbb R}^+$ are the bounds on energy costs defined in \eqref{uU-condition} and $d$ is the branching number of the tree. \\
Denote by $B_v$ the bad event 
that there exists a contour around $v$ with respect to $\omega$ which 
does not have good enough excess energy in the sense that 
\begin{equation}
\begin{split}
B_v&:=\bigcup_{\gamma:\gamma \ni v}B(\gamma) \text{ where }
B(\gamma):=\{\omega: | D(\omega)\cap E(\gamma) | 
\geq \delta_0 |\gamma|\}.
\end{split}
\end{equation}

Suppose that $\mu$ is a homogeneous tree-indexed Markov chain for a Hamiltonian in the class \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}. Let $p_1=p_1(\mu)$ be its lazyness parameter as  in Defintion \ref{def-p1}. Let $\delta_0$ as in \eqref{def-delta0}. Define $\lambda(p_1)=\lambda(p_1,u,U,d)$ as
	\begin{equation}
		\begin{split}
			\label{def-lambda-p1}
			&e^{-\lambda(p_1)}:= 
			\inf_{t\geq 0}e^{-t \delta_0}
			(p_1 e^t+1-p_1)^{(d+1)}
			=\left(\frac{p_1}{\delta_0}\right)^{\delta_0}\Bigl(\frac{1-p_1}{d+1-\delta_0} \Bigr)^{1-\delta_0}.
		\end{split}
	\end{equation}
	Note that $\lambda(p_1)\uparrow\infty$ or equivalently $e^{-\lambda(p_1)}\downarrow 0  \text{ as } 
	p_1\downarrow 0$. In particular, if $\mu_\beta$ is the free state of the $q$-clock model at inverse temperature $\beta$ (see \eqref{p1-free-clock}),
	$$\lambda(p_1(\mu_\beta))\uparrow \infty  \text{ as } 
	\beta\uparrow \infty.$$

\label{key-lemma}


Let $\mu$ be the central state of any model {with Hamiltonian} in the class \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}. Then for $\beta$ large enough we have, for $\mu$-almost every\ $\omega$
{
\begin{equation}
\begin{split}
\label{eq-bad-dec}\pi(\sigma_v\neq \omega_v|\omega)

\leq   1_{B_v}(\omega) + \epsilon_1(\beta)
\end{split}
\end{equation}
where the event $B_v$ is defined in \eqref{def-bad}, 
and 
$\epsilon_1(\beta)\downarrow0$ as $\beta\uparrow\infty$.









Moreover, 

\begin{equation}\label{proba-bad-contour}
	\mu(B(\gamma))\leq e^{-\lambda(p_1)|\gamma|}
\end{equation}
where $\lambda(p_1)$ is defined in \eqref{def-lambda-p1} and for $p_1$ small enough, for any $v\in V$

\begin{equation}\label{proba-bad-at-v}
	m(p_1):=\mu(B_v)\leq \epsilon_2(p_1)

\end{equation}
where $\epsilon_2(p_1)\downarrow0$ as $p_1\downarrow0$.












}

{We decompose 
\begin{align}
	\pi(\sigma_v\neq \omega_v|\omega)=\pi(\sigma_v\neq \omega_v|\omega)(1_{B_v}(\omega)+1_{B^c_v}(\omega))
\end{align}
and} we use the {infinite-volume} version of the Peierls bound of Lemma \ref{lem-Peierls} (removing the restriction to finite volume always gives an upper bound) applied to the complement of a bad event at $v$ to bound 
the probability of a mismatch at $v$ by the sum over contours attached at $v$. 
This gives  
\begin{equation}
\begin{split}
\label{XSpSOS2-4l}&
\pi(\sigma_v\neq \omega_v|\omega)1_{B^c_v}(\omega)
\leq \sum_{\bar \gamma, \gamma \ni v}\rho[\omega](\bar \gamma)1_{B^c_v}(\omega)
\end{split}
\end{equation}
where $\rho[\omega](\bar \gamma)$ is the contour activity relative to $\omega$. 
Note that $\omega$ is not assumed to be a local ground state ({in the sense of \cite{CoKuLe22}}), but we may 
still use the bound on the excess energy of a local perturbation {given in Lemma \ref{lem-EEL}}. \\
This delivers, using the assumptions on the potential in the class \eqref{potential-central} and the Definition \ref{def-bad} of $B_v$,
\begin{equation}
\begin{split}
&\rho[\omega](\bar \gamma)1_{B^c_v}(\omega)\cr
&\leq \exp({-\beta (d-1)u |\gamma| + \beta(u+U) | D(\omega)\cap E(\gamma) | +{\Vert\Psi\Vert}_\infty|\gamma|
})1_{B^c_v}(\omega)\cr
&\leq \exp({-\beta |\gamma|((d-1)u - (u+U)\delta_0 -{\Vert\Psi\Vert}_\infty)})\cr
&=\exp({-\beta |\gamma| {(d-1)u}/4 })
\end{split}
\end{equation} 
Using the {entropy bound of Lemma \ref{lem-entropy}} 
we deduce that there exists $C',c'>0$ such that
\begin{equation}
\begin{split}
\label{def-epsilon1-beta}&
\pi(\sigma_v\neq \omega_v|\omega)1_{B^c_v}(\omega)
\leq \sum_{\bar \gamma, \gamma \ni v}e^{-\beta c |\gamma|}
{\leq\sum_{\ell\geq1}(d+1)^{2(\ell-1)}(q-1)^\ell e^{-\beta  \ell (d-1)u/4}}\cr
&\leq C' e^{-c' \beta}=:\epsilon_1(\beta)
\end{split}
\end{equation}
for $\beta>4\log((q-1)(d+1)^2)/(u(d-1))$, which proves \eqref{eq-bad-dec}. 



Next we use the exponential Markov inequality to bound $\mu(B_v(\gamma))$ 
and sum over the contours afterwards to bound 
$\mu(B_v)$, as will be described now. 
\begin{align}
	\mu(B_v(\gamma))
	&=\mu\bigl(	 | D(\omega)\cap E(\gamma) | 
	\geq \delta_0 |\gamma|\bigr)\\
	&\leq \inf_{t\geq 0}e^{-t \delta_0 |\gamma|}\mu(e^{t  | D(\omega)\cap E(\gamma) | 
		}) 
\end{align}

It suffices to fix any $x\in \gamma$, look at the conditional measure  
$\mu_a(\cdot ):=\mu(\cdot |\sigma_x=a )$ for any fixed $a\in {\mathbb Z}_q$, and find an upper bound which does not depend on $a$. 


Using the Markov chain property of the measure $\mu_a$, successive applications of the homogeneous transition matrix 
$P$ yield
\begin{equation}
\begin{split}
\label{exp-Markov-Bv}
&\mu_a(e^{t  | D(\omega)\cap E(\gamma) | })\leq (p_1 e^t+1-p_1)^{(d+1)|\gamma|}  
\end{split}
\end{equation}
which follows from $$\max_{a\in{\mathbb Z}_q} \sum_{b\neq a}P(a,b)e^t +P(a,a) \leq p_1 e^t + 1-p_1$$ 
and the bound $|E( \gamma) |\leq (d+1)|\gamma|.$
Optimizing over $t$ leads to the bound 
\begin{equation}
\begin{split}
\label{XSpSOS2-4i}
&\mu(B_v(\gamma)){\leq \Bigl(\inf_{t\geq 0}e^{-t \delta_0}
(p_1 e^t+1-p_1)^{(d+1)}  \Bigr)^{|\gamma|}}= e^{-\lambda(p_1)|\gamma|}
\end{split}
\end{equation}
which proves \eqref{proba-bad-contour}, since the definition \eqref{def-lambda-p1} of $\exp(-\lambda(p_1))$ is made to be the value of the above infimum.
Finally using the {entropy bound of Lemma \ref{lem-entropy}} on the number of contours of fixed length 
which are attached to a given point, the estimate for 
$\mu(B_v)$ follows. Indeed, there exists $C>0$ such that for any $c\in(0,1)$ we have
{
\begin{align}\label{def-epsilon2-p1}
	m(p_1):=\mu(B_v)&\leq
	\sum_{\gamma:\gamma\ni v}\mu(B_v(\gamma))
	\leq \sum_{\gamma:|\gamma|\geq 1}e^{-\lambda(p_1)|\gamma|}\nonumber\\
	&\leq \sum_{\ell\geq1}(d+1)^{2(\ell-1)} (q-1)^\ell e^{-\lambda(p_1)\ell}\cr
		&\leq C e^{-c\lambda(p_1)}=:\epsilon_2(p_1)
\end{align}
for $p_1$ sufficiently small, which proves \eqref{proba-bad-at-v}.}
\endproof

The proof is short and elementary, given the reconstruction bound of Theorem \ref{thm-reconstruction}. 
Observe that 
\begin{equation}\label{qEA1}
	\begin{split}
	&q_{\rm EA}^\mu=\sum_{a \in {\mathbb Z}_q}\Bigl(\mu\Bigl( \pi( {\sigma_0=a} | \cdot)^2
\Bigr)	- 
	\mu(\sigma_0=a)^2 \Bigr)\cr
	&=\sum_{a\in {\mathbb Z}_q}\Bigl(\sum_{b \in {\mathbb Z}_q}\mu(\sigma_0=b)\mu\Bigl( \pi( {\sigma_0=a} | \cdot)^2
|\sigma_0=b\Bigr)	- 
	\mu(\sigma_0=a)^2 \Bigr)\cr
	&\geq \sum_{a \in {\mathbb Z}_q}\Bigl(\mu(\sigma_0=a)\mu\Bigl( \pi( {\sigma_0=a} | \cdot)^2
|\sigma_0=a\Bigr)	- 
	\mu(\sigma_0=a)^2 \Bigr)\cr
\end{split}
	\end{equation}
which, by the quantitative reconstruction Theorem \ref{thm-reconstruction} gives the lower bound 
	\begin{equation}\label{qEA1}
	\begin{split}
		q_{\rm EA}^\mu&\geq \sum_{a \in {\mathbb Z}_q}\Bigl(\mu(\sigma_0=a)
	(1-\epsilon_1(\beta))^2 (1- \epsilon_2(p_1))
	-\mu(\sigma_0=a)^2 \Bigr)\\
	&\geq(1-\epsilon_1(\beta))^2 (1- \epsilon_2(p_1))
	-\max_{a\in{\mathbb Z}_q}\mu(\sigma_0=a)
\end{split}
	\end{equation}
which proves the theorem.

\label{lem-decorr}  {Consider the central state $\mu$ of any model {with Hamiltonian} in the class} \eqref{potential-central} fulfilling the bounds \eqref{uU-condition} and \eqref{hyp-psi}.
Suppose that the transition matrix $P$ of the state $\mu$ is irreducible 
and aperiodic. Recall the Definition \ref{def-bad} of a bad event $B_v$ at $v\in V$ and the notation for its expectation $\mu(B_v)=:m(p_1)$ (which does not depend on $v$).
Let 
\begin{equation}\label{def-cov-uv}
	\mbox{$\mathrm Cov$}(u,v):=\mu\Bigl((1_{B_v}(\omega)-m(p_1))(1_{B_u}(\omega)-m(p_1))\Bigr).
\end{equation}
Then for small enough $p_1$, there exist $C>0$ such that for any $c_1\in(0,\frac13)$ and $c_2\in(0,1)$, for any $u,v\in V$,
\begin{equation}
\begin{split}
\label{exp-decay-cov}
|\mbox{$\mathrm Cov$}(u,v)|

&\leq C e^{- c |v-u|}
\end{split}
\end{equation}
where $|v-u|$ is the graph distance in the tree and
\begin{equation}
\begin{split}
\label{X22}
&e^{- c}=\max\{e^{-c_1\lambda(p_1)},|\lambda_2(P)|^{c_2} \}
\end{split}
\end{equation}
where $\lambda(p_1)$ is defined in \eqref{def-lambda-p1} and $\lambda_2(P)$ is the second largest eigenvalue (in modulus)
of the transition matrix $P$ of $\mu$.

We first define several objects and events which are depicted on Figure~\ref{fig-badbad}.
\begin{figure}
	\begin{center}
	\includegraphics[width=10cm]{decorr.png}
	\caption{Objects appearing in the proof of Lemma \ref{lem-decorr} of exponential decorrelation of bad events at $u$ and $v$. On the picture $d=2,|u-v|=11, r=3$. Half-trees $H_u(3)$ and $H_v(3)$ are delimited by the two vertical lines. One of the midpoints between $u$ and $v$ is denoted by $x$. The support of the bad event $B_u^1$, depicted with a dashed line, stays inside $H_u(3)$, while the support of the bad event $B_v^2$, depicted with a dotted line, exits $H_v(3)$. The vertex $y$ is the closest to $u$ on the path from $u$ to $x$ which does not touch the support of $B_u^1$. }\label{fig-badbad}
	\end{center}
  \end{figure}
Denote by the half-trees $H_u(r)$ and $H_v(r)$ the sets 
\begin{equation}
\begin{split}
\label{XSpSOS2-66}
&H_u:=H_u(r):=\{x\in V, |x-u|\leq |x-v|-r\}\cr
&H_v:=H_v(r):=\{x\in V, |x-v|\leq |x-u|-r\}\cr
\end{split}
\end{equation}
We will choose $r=\lfloor |u-v|/3\rfloor$. 
Clearly $H_u$ and $H_v$ are disjoint, with their distance growing proportionally 
to $|u-v|$.  
Define 
\begin{equation}
\begin{split}
\label{bad-decomposition}
&B^1_u:=\bigcup_{\gamma: H_u\supset
\gamma \ni u}B_u(\gamma),\quad B^2_u:=B_u\backslash B^1_u\cr
&B^1_v:=\bigcup_{\gamma: H_v\supset
\gamma \ni u}B_v(\gamma),\quad B^2_v:=B_v\backslash B^1_v.\cr
\end{split}
\end{equation}
The sets $B^1_u$ and $B^1_v$ describe bad events at $u$ (resp.\ $v$) which are produced by contours
included in $H_u$ (resp.\ $H_v$). 
The sets $B^2_u$ and $B^2_v$ describe bad events which are not produced by the previous contours and may 
connect $u$ and $v$. \\



















Bad event caused by long contours are exponentially improbable 
in the minimal length of such contours. Namely, by the Key Lemma \ref{key-lemma} and the entropy bound given in Lemma \ref{lem-entropy}, there exist $C_1>0$ such that for any $c_1\in(0,\frac13)$ we have
{
\begin{equation}
\begin{split}
\label{}
\mu(B^2_u)=\mu(B^2_v)&\leq 
\sum_{\gamma: \gamma \ni u, \gamma \cap H^c_u\neq \emptyset}\mu(B_u(\bar\gamma))
\leq \sum_{\gamma: \gamma \ni u, |\gamma|\geq|u-v|/3}
e^{-\lambda(p_1)|\gamma|}\\
&\leq \sum_{\ell\geq|u-v|/3}(d+1)^{2(\ell-1)}(q-1)^\ell e^{-\lambda(p_1)\ell}\\
&\leq C_1 \exp({-c_1\lambda(p_1)|u-v|}).
\end{split}
\end{equation}}




Spelling out the correlation function between the bad events in terms 
of the decomposition \eqref{bad-decomposition}, we therefore have 
\begin{equation}
\begin{split}
\label{XSpSOS2-99}
&|\mbox{$\mathrm Cov$}(u,v)|=|\mu(B^1_u;B^1_v)+\mu(B^1_u;B^2_v)+\mu(B^2_u;B^1_v)+\mu(B^2_u;B^2_v)|\cr
&\leq |\mu(B^1_u;B^1_v)|+ 3 \min\{\mu(B^2_u),\mu(B^2_v)\}\\
&\leq |\mu(B^1_u;B^1_v)|+ 3C_1 \exp({-c_1\lambda(p_1)|u-v|}).\cr

\end{split}
\end{equation}
It remains to control the decay of $|\mu(B^1_u;B^1_v)|$. 
We would have the exact decorrelation 
$\mu(B^1_u;B^1_v)=0$ in the free state of a clock model, but 
for an non-symmetric model there is no reason to assume that such 
decorrelation holds.  
Nevertheless, we may use the {Markov chain} property of $\mu$ along the path from $u$ to $v$ and 
the exponential convergence of the corre{s}ponding {1d-}Markov chain, to arrive 
at the decorrelation which is exponential in the distance $|u-v|$ (with our irreducibility and aperiodicity assumptions).

Indeed, choose $x=x(u,v)$ to be the (or one of the at most two) middle sites
between $u$ and $v$ (which means that the distances $|u-x|$ and $|v-x|$ differ at most by one).
From the tree-indexed Markov chain property of $\mu$, using conditional independence, we have 
\begin{equation}
\begin{split}
\label{XSpSOS2-yy}
&\mu(B^1_u\cap B^1_v)=\sum_{a\in{\mathbb Z}_q} \mu(B^1_u|\sigma_x=a)\mu(B^1_v|\sigma_x=a)\mu(\sigma_x=a).
\end{split}
\end{equation}
Let $\Delta_{u,x}(a):=\mu(B^1_u|\sigma_x=a)-\mu(B^1_u)$ and similarly for $v$. We have 
 \begin{align}
\label{XSpSOS2-jj}
|\mu(B^1_u; B^1_v)|&	=
\big|\sum_{a\in{\mathbb Z}_q} \Bigl(\mu(B^1_u)\Delta_{v,x}(a)+\mu(B^1_v)\Delta_{u,x}(a)+\Delta_{u,x}(a)\Delta_{v,x}(a)\Bigr)\mu(\sigma_x=a)\big|\nonumber\\
&\leq2\max_{a\in{\mathbb Z}_q}|\Delta_{u,x}(a)|+\max_{a\in{\mathbb Z}_q}|\Delta_{v,x}(a)|.
\end{align}
By symmetry it suffices to bound $|\Delta_{u,x}(a)|$. 
Choose $y$ on the path $[x,u]$, between $x$ and $u$, such that it is the closest to $u$ with the property that all the contours appearing in the definition of $B^1_u$ do not touch 
$(x,y]$. 

To control the difference between $\mu(B^1_u|\sigma_x=a)$ and $\mu(B^1_u)$
we use the exponential relaxation of the homogenous 1d Markov chain which arises as restriction of $\mu$, on the path from  $x$ to $y$.
There exists $C_2>0$ such that for any $c_2\in(0,1)$, 
\begin{equation}
\begin{split}
\label{exp-decorrelation-1dMC}
&|\Delta_{u,x}(a)|=|\sum_{b\in{\mathbb Z}_q} \mu(B^1_u|\sigma_y=b)( \mu(\sigma_y=b|\sigma_x=a) -\mu(\sigma_y=b))|\cr
&\leq \sum_{b\in{\mathbb Z}_q} |\mu(\sigma_y=b|\sigma_x=a) -\mu(\sigma_y=b))|\cr
&=\sum_{b\in{\mathbb Z}_q} |P^{|x-y|}(a,b) -\mu(\sigma_y=b))|\cr
&\leq C_2 |\lambda_2(P)|^{c_2|x-y|}
\end{split}
\end{equation}
where the last line follows e.g.\ from \cite[Example 4.3.9: 
Rates of Convergence via the Perron-Frobenius Theorem]{Bremaud}. 
As by construction $|y-x|\sim \frac{1}{6}|u-v|$, as $|u-v|\uparrow\infty$, this implies the 
desired exponential decorrelation of  $|\mu(B^1_u;B^1_v)|$, and concludes the proof. 
\endproof

